import json

# Let me be extremely thorough with the JSON file
with open('/app/resources/treasury_bulletin_2003_03.json') as f:
    data = json.load(f)

# Check the entire structure
def explore(obj, depth=0, max_keys=50):
    if isinstance(obj, dict):
        count = 0
        for k, v in obj.items():
            print("  "*depth + f"{k}: {type(v).__name__}")
            count += 1
            if count > max_keys:
                break
            if isinstance(v, (dict, list)) and depth < 2:
                explore(v, depth+1)
    elif isinstance(obj, list) and depth < 2:
        print("  "*depth + f"list[{len(obj)}]")
        if obj:
            print("  "*depth + f"First: {type(obj[0]).__name__}")

explore(data)
EOF
